<?php
namespace Core;require_once __DIR__.'/Guard.php';ml_guard_shield(__FILE__);class CrossLink{const TMDB_DELAY_SEC=0.3;const MIN_LEN=4;const MIN_RATING=6.0;public static function cfg(){$a=Config::get('crosslink',array());if(!is_array($a)){$a=array();}$b=array('enable'=>1,'auto_after_sync'=>1,'batch_size'=>20,'min_rating'=>self::MIN_RATING,'match_level'=>3,'dry_run'=>0,);$c=$b;foreach($b as $d=>$e){if(array_key_exists($d,$a)&&$a[$d]!==''&&$a[$d]!==null){$c[$d]=$a[$d];}}$c['enable']=(int)$c['enable'];$c['auto_after_sync']=(int)$c['auto_after_sync'];$c['batch_size']=max(1,min(200,(int)$c['batch_size']));$c['min_rating']=max(0.0,min(10.0,(float)$c['min_rating']));$c['match_level']=max(1,min(3,(int)$c['match_level']));$c['dry_run']=(int)$c['dry_run'];return $c;}public static function enrich(array $a,array $b=array()){$c=microtime(true);$d=self::cfg();$e=!empty($b['force']);$f=isset($b['limit'])?max(1,(int)$b['limit']):max(1,(int)$d['batch_size']);$g=(bool)$d['dry_run'];$h=array('checked'=>0,'linked'=>0,'skipped'=>0,'errors'=>0,'ms'=>0,'dry_run'=>$g,'min_rating'=>$d['min_rating'],'match_level'=>$d['match_level'],'items'=>array(),'from'=>'tmdb ⇋ hongguoduanju',);$i=self::filterBySource($a,'hongguoduanju',$e);$h['checked']+=count($i);$j=self::linkShortToTmdb($i,$f,$g,$d);$h['items']=array_merge($h['items'],$j['items']);$h['linked']+=$j['linked'];$h['skipped']+=$j['skipped'];$h['errors']+=$j['errors'];$h['tmdb_calls']=$j['tmdb_calls'];$k=self::filterBySource($a,'tmdb',$e);$h['checked']+=count($k);$l=self::linkTmdbToShort($k,$f,$g,$d);$h['items']=array_merge($h['items'],$l['items']);$h['linked']+=$l['linked'];$h['skipped']+=$l['skipped'];$h['errors']+=$l['errors'];$h['short_calls']=$l['short_calls'];$h['ms']=(int)round((microtime(true)-$c)*1000);return $h;}private static function linkShortToTmdb(array $a,$b,$c,array $d){$e=array('linked'=>0,'skipped'=>0,'errors'=>0,'tmdb_calls'=>0,'items'=>array());if(empty($a))return $e;if(count($a)>$b)$a=array_slice($a,0,$b);$f=self::tmdbAdapter();if($f===null)return $e;foreach($a as $g){$h=CacheStore::getRowById((int)$g);if(!$h){$e['skipped']++;continue;}$i=(string)(isset($h['title'])?$h['title']:'');if(trim($i)===''){$e['skipped']++;continue;}$j=self::matchTmdb($f,$i,$d);if($j===null){$e['items'][]=array('id'=>(int)$g,'title'=>$i,'action'=>'无 TMDB 匹配');continue;}$k=self::jsonDecode($h['extra']);$l=self::appendTmdbLink($k,$j);$m=array();$n=isset($h['rating'])?$h['rating']:null;if(($n===null||$n===''||$n==='0'||$n===0)&&is_numeric($j['rating'])&&$j['rating']>0){$m['rating']=(float)$j['rating'];}$o=isset($h['vote_count'])?$h['vote_count']:null;if(($o===null||$o===''||$o==='0'||$o===0)&&is_numeric($j['vote_count'])&&(int)$j['vote_count']>0){$m['vote_count']=(int)$j['vote_count'];}if(empty($h['overview'])&&!empty($j['overview'])){$m['overview']=$j['overview'];}if(empty($h['poster'])&&!empty($j['poster'])){$m['poster']=$j['poster'];}$p=is_array($h['genres'])?$h['genres']:self::parseGenresField($h['genres']);$q=self::mergeGenres($p,isset($j['genres'])?$j['genres']:array());if($q!==$p){$m['genres']=$q;}if($l!==$k){$m['extra']=$l;}$r=!empty($m);if(!$r){$e['items'][]=array('id'=>(int)$g,'title'=>$i,'action'=>'已匹配但未产生变更（字段已完整）','tmdb'=>self::tmdbMeta($j),);$e['skipped']++;continue;}if(!$c){try{CacheStore::updateById((int)$g,$m);}catch(\Exception $s){$e['errors']++;$e['items'][]=array('id'=>(int)$g,'title'=>$i,'action'=>'写入失败：'.$s->getMessage());continue;}}$e['linked']++;$e['items'][]=array('id'=>(int)$g,'title'=>$i,'action'=>'已从 TMDB 补：'.implode('，',array_keys($m)),'tmdb'=>self::tmdbMeta($j),);usleep(self::TMDB_DELAY_SEC*1000000);$e['tmdb_calls']++;}return $e;}private static function linkTmdbToShort(array $a,$b,$c,array $d){$e=array('linked'=>0,'skipped'=>0,'errors'=>0,'short_calls'=>0,'items'=>array());if(empty($a))return $e;if(count($a)>$b)$a=array_slice($a,0,$b);foreach($a as $f){$g=CacheStore::getRowById((int)$f);if(!$g){$e['skipped']++;continue;}$h=(string)(isset($g['title'])?$g['title']:'');if(trim($h)===''){$e['skipped']++;continue;}$i=self::matchShort($h,$d);if($i===null){$e['items'][]=array('id'=>(int)$f,'title'=>$h,'action'=>'无短剧匹配');continue;}$j=self::jsonDecode($g['extra']);$k=array();if(!isset($j['play_count_from_short'])||$j['play_count_from_short']!==$i['play_count']){$j['play_count_from_short']=(int)$i['play_count'];$j['episodes_from_short']=isset($i['episodes'])?(int)$i['episodes']:null;$j['duration_from_short']=isset($i['duration'])?(string)$i['duration']:'';$j['publish_time_from_short']=isset($i['publish_time'])?(string)$i['publish_time']:'';$j['record_number_from_short']=isset($i['record_number'])?(string)$i['record_number']:'';$j['short_source']='hongguoduanju';$j['short_source_id']=(string)$i['source_id'];$j['short_title']=(string)$i['title'];$j['cross_linked_at']=date('Y-m-d H:i:s');$k['extra']=$j;}if(empty($k)){$e['items'][]=array('id'=>(int)$f,'title'=>$h,'action'=>'已链接，无需更新');$e['skipped']++;continue;}if(!$c){try{CacheStore::updateById((int)$f,$k);}catch(\Exception $l){$e['errors']++;$e['items'][]=array('id'=>(int)$f,'title'=>$h,'action'=>'写入失败：'.$l->getMessage());continue;}}$e['linked']++;$e['items'][]=array('id'=>(int)$f,'title'=>$h,'action'=>'已从短剧补：'.implode('，',array_keys($k)).'（短剧「'.$i['title'].'」）',);$e['short_calls']++;}return $e;}private static function matchTmdb($a,$b,array $c){try{$d=$a->search($b,1,'');}catch(\Exception $f){return null;}if(!is_array($d)||empty($d['items'])){return null;}$e=self::normTitle($b);if($e==='')return null;$g=(int)$c['match_level'];$h=(float)$c['min_rating'];$i=null;$j=0;foreach($d['items']as $k){$l=isset($k['rating'])?(float)$k['rating']:0.0;if($l<$h)continue;$m=self::normTitle((isset($k['title'])?$k['title']:'').'|'.(isset($k['original_title'])?$k['original_title']:''));$n=self::titleHit($e,$m,$g);if($n>$j){$j=$n;$i=$k;}if($j>=3)break;}return $i;}private static function matchShort($a,array $b){try{$c=self::normTitle($a);if($c==='')return null;$d=(int)$b['match_level'];$e=\Core\CacheStore::searchItems($a,'','hongguoduanju',1,20);if(!is_array($e))return null;$f=isset($e['items'])&&is_array($e['items'])?$e['items']:array();$g=null;$h=0;foreach($f as $i){if(!is_array($i))continue;$j=self::normTitle((isset($i['title'])?$i['title']:'').'|'.(isset($i['original_title'])?$i['original_title']:''));$k=self::titleHit($c,$j,$d);if($k>$h){$h=$k;$g=$i;}if($h>=3)break;}if($g===null)return null;$l=self::jsonDecode(isset($g['extra'])?$g['extra']:'');return array('source_id'=>isset($g['source_id'])?(string)$g['source_id']:'','title'=>isset($g['title'])?(string)$g['title']:'','play_count'=>(int)(isset($l['play_count'])?$l['play_count']:0),'episodes'=>(int)(isset($l['episodes'])?$l['episodes']:0),'duration'=>(string)(isset($l['duration_raw'])?$l['duration_raw']:''),'publish_time'=>(string)(isset($l['publish_time'])?$l['publish_time']:''),'record_number'=>(string)(isset($l['record_number'])?$l['record_number']:''),);}catch(\Exception $m){return null;}}private static function titleHit($b,$a,$c){if($b===''||$a==='')return 0;if($b===$a)return 3;if($c<2)return 0;$d=min(strlen($b),strlen($a));if($d<self::MIN_LEN)return 0;if(strpos($b,$a)===0||strpos($a,$b)===0)return 2;if($c<3)return 0;$e=strlen($b)<=strlen($a)?$b:$a;$f=strlen($b)<=strlen($a)?$a:$b;if(strlen($e)<self::MIN_LEN)return 0;if(strpos($f,$e)!==false)return 1;return 0;}public static function normTitle($a){$a=(string)$a;$a=preg_replace('/[\s\p{P}]+/u','',$a);$a=mb_strtolower($a,'UTF-8');$b=array('的'=>'的','们'=>'们','个'=>'个','来'=>'来','说'=>'说','东'=>'东','马'=>'马','鱼'=>'鱼','车'=>'车','长'=>'长','龙'=>'龙','门'=>'门','书'=>'书','东'=>'东','万'=>'万',);$a=str_replace(array_keys($b),array_values($b),$a);return $a;}private static function tmdbAdapter(){try{$file=__DIR__.'/../adapters/Tmdb.php';if(!file_exists($file))return null;require_once $file;$cls='\\Adapters\\Tmdb';if(!class_exists($cls))return null;return new $cls;}catch(\Exception $e){return null;}}private static function tmdbMeta(array $a){return array('source_id'=>isset($a['source_id'])?(string)$a['source_id']:'','title'=>isset($a['title'])?(string)$a['title']:'','year'=>isset($a['year'])?(int)$a['year']:null,'rating'=>isset($a['rating'])?(float)$a['rating']:null,'vote_count'=>isset($a['vote_count'])?(int)$a['vote_count']:0,);}private static function appendTmdbLink($a,array $b){if(!is_array($a))$a=array();if(!isset($a['tmdb_links'])||!is_array($a['tmdb_links'])){$a['tmdb_links']=array();}$c=self::tmdbMeta($b);$a['tmdb_links'][$c['source_id']]=$c;$a['cross_linked_at']=date('Y-m-d H:i:s');return $a;}private static function mergeGenres(array $b,array $a){$c=array();foreach(array_merge($b,$a)as $d){$d=trim((string)$d);if($d===''||in_array($d,$c,true))continue;$c[]=$d;}return $c;}private static function parseGenresField($a){if(is_array($a))return $a;$a=(string)$a;if($a==='')return array();$b=json_decode($a,true);if(is_array($b))return $b;$c=explode(',',$a);$d=array();foreach($c as $e){$e=trim($e);if($e!=='')$d[]=$e;}return $d;}private static function jsonDecode($a){if(is_array($a))return $a;$a=(string)$a;if($a==='')return array();$b=json_decode($a,true);return is_array($b)?$b:array();}private static function filterBySource(array $a,$b,$c){if(empty($a))return array();$d=DB::pdo();$e=array_fill(0,count($a),'?');$f='SELECT id, extra FROM media_items WHERE id IN ('.implode(',',$e).') AND source=?';$g=array_values($a);$g[]=$b;$h=$d->prepare($f);$h->execute($g);$i=$h->fetchAll(\PDO::FETCH_ASSOC);$j=array();foreach($i as $k){if(!$c){$l=self::jsonDecode(isset($k['extra'])?$k['extra']:'');if(isset($l['cross_linked_at'])&&$l['cross_linked_at']!==''){continue;}}$j[]=(int)$k['id'];}return $j;}}